{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The dynamic ingress blocks do not include a 'description' argument, which is required for auditability and compliance with AWS best practices."
    },
    {
      "check_id": "CKV_AWS_24",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 22",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "The ingress rules explicitly allow traffic from 0.0.0.0/0 (the entire internet). If var.ingress_ports includes port 22 (SSH), this creates a critical exposure. Even if it doesn't currently, allowing 0.0.0.0/0 on any port for a Vault instance is generally insecure unless strictly limited to public-facing ports like 80/443 behind a WAF/LB. Given the generic nature of the variable, restricting CIDR blocks is the safer remediation pattern."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      cidr_blocks = [\"10.0.0.0/8\"] # Restricted CIDR example; replace with actual trusted network ranges\n      description = \"Allow access to Vault on port ${port.value}\"\n    }\n  }\n}",
  "fix_summary": "Added a 'description' field to the dynamic ingress block to satisfy CKV_AWS_23. Changed the 'cidr_blocks' from the overly permissive '0.0.0.0/0' to a restricted private range ('10.0.0.0/8') as a placeholder for secure configuration, addressing the risk of unrestricted internet exposure (CKV_AWS_24 context)."
}
